import {migrate} from './migrate.js';
import {empty,uid,day,domains,progress,schedule,mastery,seed,spentToday,reviewPending,reviewReady,normalize,ensureMilestones,milestoneProgress,routeProgress,timeline,focusElapsed,ensureStages,stageStatuses,updateStage,syncStageResult} from './model.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state,revision=0,dirty=false,saving=false,ready=false,saveAgain=false,currentDate=day(),filter={domain:'全部',status:'全部',search:'',due:'全部'},activeSession=null,tick;
const labels={today:'今日行动',tasks:'任务计划',calendar:'日程安排',goals:'长期目标',projects:'项目推进',review:'整理与复盘'};
let taskLayout='table',taskScope='all',reviewTab='night',selectedTaskId=null;
const view=()=>location.hash.slice(1)||'today';
const options=(list,value)=>list.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('');
const button=(text,action,id='',cls='secondary')=>`<button class="${cls}" data-action="${action}" data-id="${esc(id)}">${text}</button>`;
const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500);}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`个人工作台-${day()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
async function load(){try{const r=await fetch('/api/workspace');const data=await r.json();if(!r.ok)throw Error(data.error);state=data.data||empty();revision=data.revision;ready=true;dirty=false;const normalized=normalize(state),migrated=migrate(state),stagesChanged=ensureStages(state);$('#sync').textContent='云端已连接';$('#notice').textContent='';render();if(normalized||migrated||stagesChanged)persist();}catch(e){$('#storageTools').open=true;$('#sync').textContent='连接失败';$('#notice').textContent=e.message+' 可点击「加载云端」重试。';}}
async function persist(){dirty=true;if(saving){saveAgain=true;return;}saving=true;$('#sync').textContent='正在保存…';try{const snapshot=JSON.stringify(state);const r=await fetch('/api/workspace',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision,data:JSON.parse(snapshot)})});const result=await r.json();if(!r.ok)throw Error(result.error);revision=result.revision;dirty=JSON.stringify(state)!==snapshot;$('#sync').textContent=dirty?'等待保存…':'已保存到云端';$('#notice').textContent='';}catch(e){saveAgain=false;$('#storageTools').open=true;$('#sync').textContent='尚未保存';$('#notice').textContent=e.message+' 当前修改保留在此页面，请勿关闭；可重试保存或导出备份。';}finally{saving=false;if(saveAgain){saveAgain=false;persist();}}}
function change(fn){fn();persist();render();}
function show(html,mode=''){if(mode==='drawer'){if($('#dialog').open)$('#dialog').close();$('#inspector').hidden=false;$('#appWindow').classList.add('with-inspector');$('#inspectorBody').innerHTML=html;$('#inspectorLabel').textContent='任务详情';markSelection();return;} $('#dialog').className=mode;$('#dialogBody').innerHTML=`<button class="close" data-action="close" aria-label="关闭">×</button>${html}`;if(!$('#dialog').open)$('#dialog').showModal();}
function close(){if(activeSession){pauseFocus();setPhase('result');toast('先保存本次进展，再返回首页。');return;}$('#dialog').close();if(selectedTaskId&&!$('#inspector').hidden)openTask(selectedTaskId);}
function taskRow(t){return `<div class="task"><div class="task-main">${button(esc(t.name),'task',t.id,'task-name')}<div class="meta-line">${statusBadge(t)}<span>${esc(t.domain)}</span><span>${t.minutes} 分钟</span>${t.due?`<span class="${t.due<day()&&t.status!=='完成'?'overdue':''}">${esc(t.due)}</span>`:''}</div></div>${button(t.status==='完成'?'查看记录':t.resume?'继续':'开始',t.status==='完成'?'task':'execute',t.id,'text-button')}</div>`;}
function stateGroup(t){if(reviewPending(t))return '待复测';if(t.status==='完成')return '已完成';if(['进行中','部分完成'].includes(t.status))return '进行中';if(['等待','以后'].includes(t.status))return '暂缓';return '待开始';}
function statusBadge(t){const label=stateGroup(t),key={'待开始':'todo','进行中':'active','待复测':'review','已完成':'done','暂缓':'paused'}[label];return `<span class="status ${key}">${label}</span>`;}
function recurringForDate(date){const weekday=new Date(date+'T12:00:00').getDay();return (state.automations||[]).filter(a=>a.enabled&&(a.frequency==='daily'||a.weekdays?.includes(weekday))).sort((a,b)=>(a.time||'').localeCompare(b.time||''));}
function recurringRow(a){return `<div class="agenda-item recurring-item"><time>${esc(a.time||'—')}<br><small>自动安排</small></time><div><strong>${esc(a.title)}</strong><small>${esc(a.description||'')}</small></div><span class="recurring-mark">${a.mergedCount>1?'已合并':'自动'}</span></div>`;}
function pageHead(title,desc,action=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;}
function blank(title,text,action=''){return `<div class="empty-state"><strong>${title}</strong><p>${text}</p>${action}</div>`;}
function relations(t){const m=state.goals.flatMap(g=>g.milestones||[]).find(m=>m.id===t.milestone);return [...t.goals.map(id=>state.goals.find(g=>g.id===id)?.name).filter(Boolean),m?.name,state.projects.find(p=>p.id===t.project)?.name].filter(Boolean).map(esc).join(' · ')||'未关联';}

function intro(title,desc){return `<h1>${title}</h1><p class="muted">${desc}</p>`;}

function taskGoal(t){return t&&(state.goals.find(g=>g.milestones?.some(m=>m.id===t.milestone))||state.goals.find(g=>g.id===t.goals?.[0]));}
function routeContext(t){const g=taskGoal(t),m=g?.milestones?.find(m=>m.id===t.milestone);return g?'<div class="action-context"><a href="#goals">'+esc(g.name)+'</a>'+(m?button(esc(m.name),'milestone',m.id,'text-button'):'')+'</div>':'';}
function today(){const plan=schedule(state),now=plan.core[0]||plan.quick[0],rest=[...plan.core,...plan.quick].filter(t=>t.id!==now?.id).slice(0,3),g=taskGoal(now)||state.goals.find(g=>g.primary)||state.goals[0],p=g?routeProgress(state,g):null;
const task=now?routeContext(now)+'<p class="section-label">'+(now.resume?'接着上次做':'现在做什么')+'</p><h2>'+esc(now.name)+'</h2><p class="first-action">'+esc(now.resume||now.minimumAction||now.minimum||now.steps[0]||'先做十分钟，再留下结果。')+'</p><div class="action-finish"><span>完成标准</span><p>'+esc(now.criteria||'留下可以检查的成果或明确卡点。')+'</p></div><div class="now-footer">'+statusBadge(now)+'<span>约 '+(now.duration||now.estimate)+' 分钟</span>'+button(now.resume?'继续专注':'开始专注','execute',now.id,'primary')+'<a href="#tasks">换一件事</a></div>':'<h2>'+(!state.tasks.length?'开始你的第一项行动':plan.unscheduled.length?'今天的剩余时间放不下这些任务':'今天可以告一段落了')+'</h2><p class="first-action">'+(!state.tasks.length?'先试一道 Python 练习，或写下现在要做的事。':plan.unscheduled.length?'缩小任务范围，或调整下方的时间预算。':'记录进展，留好下次的起点。')+'</p><div class="actions">'+(!state.tasks.length?button('开始 Python 练习','seed','','primary')+button('写下我要做的事','newTask'):plan.unscheduled.length?'<a class="primary" href="#tasks">选择一个更小的任务</a>':'<a class="primary" href="#review">记录今天的进展</a>')+'</div>';
const route=g?'<div class="route-preview-heading"><strong>'+esc(g.name)+'</strong><span>'+p.percent+'%</span></div><div class="progress"><i style="width:'+p.percent+'%"></i></div><div class="route-preview">'+(g.milestones||[]).map((m,i)=>{const mp=milestoneProgress(state,g,m);return '<div class="home-stage-row route-preview-item"><span class="stage-dot '+stageStatusClass(mp.status)+'"></span>'+button(esc(m.name),'milestone',m.id,'task-name')+'<span class="home-stage-status">'+mp.status+'</span><span class="home-stage-percent">'+mp.percent+'%</span></div>';}).join('')+'</div>':'<p class="quiet-empty">给行动确定一个方向。</p>'+button('创建主目标','newGoal');
return '<div class="home-heading"><div><p class="section-label">'+dateLabel(day())+'</p><h1>今日</h1></div><div class="capacity"><strong>'+plan.budget+'<small> 分钟</small></strong><span>今天还能投入</span></div></div><div class="action-home"><div class="action-main"><section class="now-surface">'+task+'</section><section class="home-route"><div class="section-head"><h2>正在推进</h2><a href="#goals">完整路线</a></div>'+route+'</section><section class="next-list"><div class="section-head"><h2>接下来</h2><a href="#tasks">全部任务</a></div>'+(rest.map(taskRow).join('')||'<p class="quiet-empty">先专注眼前这一项。</p>')+'</section></div><aside class="day-column"><section class="day-timeline"><div class="section-head"><h2>今日时间线</h2><a href="#calendar">安排</a></div>'+timelineMarkup(day())+'</section><details class="time-settings"><summary>时间与精力 <span>'+esc(state.settings.energy)+'</span></summary><label>今天总预算（分钟）<input id="available" type="number" min="0" max="1440" value="'+state.settings.minutes+'"></label><label>精力<select id="energy">'+options(['低','正常','很好'],state.settings.energy)+'</select></label><p>已记录 '+spentToday(state)+' 分钟。预算每天默认 120 分钟，可按实际调整。</p>'+(plan.risk?'<p class="alert">到期任务超出预算，需要缩小范围。</p>':'')+'</details><a class="day-close" href="#review">今天结束后，留下进展</a></aside></div>';}
function timelineMarkup(date){const rows=timeline(state,date),autos=recurringForDate(date);return '<div class="timeline-list">'+(rows.map(r=>'<div class="timeline-entry '+r.kind+' '+(r.conflict?'conflict':'')+'"><div class="timeline-time"><strong>'+esc(r.start)+'</strong><small>'+esc(r.end)+'</small></div><div class="timeline-content"><span class="section-label">'+(r.kind==='event'?'固定日程':'计划任务')+(r.conflict?' · 时间重叠':'')+'</span>'+button(esc(r.name),r.kind==='event'?'event':'task',r.id,'task-name')+(r.kind==='task'?button('开始','execute',r.id,'text-button'):'')+'</div></div>').join('')||'<p class="quiet-empty">还没有安排时间。课程、训练或任务安排后会出现在这里。</p>')+'</div>'+(autos.length?'<details class="automation-notes"><summary>ChatGPT 自动安排 · '+autos.length+'</summary><p>来自 ChatGPT 定时任务的导入快照。生成内容仍在原对话，本页未持续同步。</p>'+autos.map(recurringRow).join('')+'</details>':'');}

function goalSummary(g){const p=progress(state,g);return `<div class="task"><div><strong>${esc(g.name)}${g.primary?' · 当前主目标':''}</strong><small>${p.done}/${p.total} 项完成 · ${p.mastered} 项学习已验收 · 实际投入 ${p.minutes} 分钟</small><div class="progress"><i style="width:${p.total?100*p.done/p.total:0}%"></i></div></div>${button('查看','goal',g.id)}</div>`;}
function tasks(){const list=filteredTasks(),count=[filter.domain,filter.status,filter.due].filter(v=>v!=='全部').length;return pageHead('任务',list.length+' 项任务 · 选一件，开始做',button('＋ 添加','newTask','','primary'))+`<section class="database"><div class="database-tabs">${[['all','全部'],['learning','学习'],['review','待复测']].map(([key,label])=>`<button class="view-tab ${taskScope===key?'selected':''}" data-action="scope" data-id="${key}" aria-pressed="${taskScope===key}">${label}</button>`).join('')}<div class="layout-switch">${[['table','表格'],['board','看板']].map(([key,label])=>`<button data-action="layout" data-id="${key}" class="${taskLayout===key?'selected':''}" aria-pressed="${taskLayout===key}">${label}</button>`).join('')}</div></div>
<div class="database-toolbar"><input id="search" aria-label="搜索任务" placeholder="搜索任务" value="${esc(filter.search)}"><details class="task-filters" ${count?'open':''}><summary>筛选${count?' · '+count:''}</summary><div class="filter-fields"><label>领域<select id="domainFilter">${options(['全部',...domains],filter.domain)}</select></label><label>状态<select id="statusFilter">${options(['全部','待办','进行中','部分完成','等待','以后','完成'],filter.status)}</select></label><label>截止<select id="dueFilter">${options(['全部','三天内到期'],filter.due)}</select></label><label>排序<select id="sortTasks">${options(['优先级','截止日期','最近创建'],state.settings.taskSort||'优先级')}</select></label>${button('清除筛选','resetFilters','','text-button')}</div></details></div>
${list.length?`<div class="desktop-task-view">${taskLayout==='table'?taskTable(list):taskBoard(list)}</div>${mobileTaskList(list)}`:blank('这里暂时没有任务','可以清除筛选查看全部，或添加一个具体任务。',button('新建任务','newTask','','secondary'))}<div class="database-footer">${list.length} 项任务${taskScope==='learning'&&!state.tasks.some(t=>t.template==='python-find-max-v1')?button('添加 Python 示例','seed','','text-button'):''}</div></section>`;}
function mobileTaskList(list){return '<div class="mobile-task-list">'+list.map(t=>'<article class="mobile-task-card"><div class="mobile-task-title"><span class="task-state-dot '+(t.status==='完成'?'done':'')+'" aria-hidden="true"></span>'+button(esc(t.name),'task',t.id,'task-name')+'<span aria-hidden="true">›</span></div><div class="mobile-task-content"><p class="mobile-relation">'+relations(t)+'</p><div class="meta-line">'+statusBadge(t)+'<span>'+t.minutes+' 分钟</span>'+(t.due?'<span>'+esc(t.due)+'</span>':'')+'</div><div class="mobile-task-actions">'+'<small>'+(t.status==='完成'?'已留下结果':t.domain==='学习'?'先独立尝试':'从第一步开始')+'</small>'+button(t.status==='完成'?'查看结果':t.resume?'继续专注':'开始专注',t.status==='完成'?'task':'execute',t.id,'text-button')+'</div></div></article>').join('')+'</div>';}
function filteredTasks(){let list=state.tasks.filter(t=>(taskScope!=='learning'||t.domain==='学习')&&(taskScope!=='review'||reviewPending(t))&&(filter.domain==='全部'||t.domain===filter.domain)&&(filter.status==='全部'||t.status===filter.status)&&t.name.includes(filter.search)&&(filter.due==='全部'||(t.due&&t.due<=day(new Date(Date.now()+3*86400000))&&t.status!=='完成')));const mode=state.settings.taskSort;return list.sort((a,b)=>mode==='截止日期'?(a.due||'9999').localeCompare(b.due||'9999'):mode==='最近创建'?b.created.localeCompare(a.created):a.priority-b.priority);}
function taskTable(list){return `<div class="table-scroll"><table class="task-table"><thead><tr><th>任务名称</th><th>状态</th><th>领域</th><th>优先级</th><th>截止日期</th><th>预计</th><th>目标 / 项目</th><th>操作</th></tr></thead><tbody>${list.map(t=>`<tr><td>${button(esc(t.name),'task',t.id,'task-name')}${t.resume?'<small>有上次执行记录</small>':''}</td><td><select class="cell-select task-status-cell" data-field="status" data-id="${esc(t.id)}" aria-label="${esc(t.name)}状态">${options(['待办','进行中','部分完成','等待','以后','完成'],t.status)}</select></td><td><span class="domain-label">${esc(t.domain)}</span></td><td><select class="cell-select priority-${t.priority}" data-field="priority" data-id="${t.id}" aria-label="${esc(t.name)}优先级">${[1,2,3].map(v=>`<option value="${v}" ${t.priority===v?'selected':''}>${['','高','中','低'][v]}</option>`).join('')}</select></td><td><input class="cell-date" type="date" value="${t.due||''}" data-field="due" data-id="${t.id}" aria-label="${esc(t.name)}截止日期"></td><td class="nowrap">${t.minutes} 分钟</td><td class="relation-cell">${relations(t)}</td><td>${button(t.status==='完成'?'查看':'开始',t.status==='完成'?'task':'execute',t.id,'text-button')}${button('安排时间','planTask',t.id,'text-button')}</td></tr>`).join('')}</tbody></table></div>`;}
function taskBoard(list){return `<div class="board">${['待开始','进行中','待复测','已完成','暂缓'].map(group=>{const items=list.filter(t=>stateGroup(t)===group);return `<section class="board-column"><h3>${group}<span class="count">${items.length}</span></h3>${items.map(t=>`<article class="board-card"><div class="meta-line"><span>${esc(t.domain)}</span><span class="priority-${t.priority}">${['','高优先','中优先','低优先'][t.priority]}</span></div>${button(esc(t.name),'task',t.id,'task-name')}<p class="board-relation">${relations(t)}</p><div class="meta-line"><span>${t.minutes} 分钟</span><span>${esc(t.due||'无截止日期')}</span></div><div class="board-actions">${button(t.status==='完成'?'查看结果':'开始执行',t.status==='完成'?'task':'execute',t.id,'text-button')}<select data-field="status" data-id="${t.id}" aria-label="${esc(t.name)}状态">${options(['待办','进行中','部分完成','等待','以后','完成'],t.status)}</select></div></article>`).join('')||'<p class="board-empty">暂无任务</p>'}</section>`;}).join('')}</div>`;}

function calendar(){const due=state.tasks.filter(t=>t.due===currentDate);return pageHead('日程安排','课程、训练和已安排的任务在同一条时间线上。',button('＋ 添加日程','newEvent','','primary'))+'<div class="calendar-toolbar">'+button('前一天','prevDay')+'<input id="calendarDate" aria-label="选择日期" type="date" value="'+currentDate+'">'+button('后一天','nextDay')+'</div><div class="calendar-layout"><section class="panel"><div class="section-head"><h2>'+dateLabel(currentDate)+'</h2><span>固定日程与任务</span></div>'+timelineMarkup(currentDate)+'</section><section class="panel"><h2>当天到期任务</h2>'+(due.map(taskRow).join('')||'<p class="quiet-empty">没有在这天到期的任务。</p>')+'<a href="#tasks">选择任务并安排时间</a></section></div>';}
function taskPlanForm(id){const t=state.tasks.find(t=>t.id===id);if(!t)return;show('<h2>安排任务时间</h2><p>'+esc(t.name)+' · 预计 '+t.minutes+' 分钟</p><form id="taskPlanForm" data-id="'+esc(id)+'"><label>安排日期<input name="plannedDate" type="date" value="'+esc(t.plannedDate||day())+'" required></label><label>开始时间<input name="plannedTime" type="time" value="'+esc(t.plannedTime||'19:00')+'" required></label><p class="muted">只安排时间，不改变任务的截止日期。</p><button class="primary">放入时间线</button></form>');}

function nextAction(ts){const t=ts.filter(t=>!['完成','等待','以后'].includes(t.status)||reviewReady(t)).sort((a,b)=>a.priority-b.priority)[0];return t?`<section class="direction-action"><span class="section-label">下一步行动</span><h3>${esc(t.name)}</h3><p>${esc(t.resume||t.minimum||t.steps[0]||t.criteria)}</p>${button(t.resume?'接着做':'开始这一步','execute',t.id,'primary')}</section>`:'';}
function goals(){return pageHead('目标路线','一个阶段，一项任务目标。状态、进度和日期直接修改。',button('＋ 新建路线','newGoal','','primary'))+'<div class="goal-list">'+[...state.goals].sort((a,b)=>Number(b.primary)-Number(a.primary)).map(g=>{const p=routeProgress(state,g);return '<section class="roadmap simple-roadmap"><header class="roadmap-head"><div><span class="section-label">'+(g.primary?'主路线':'目标路线')+'</span><h2>'+esc(g.name)+'</h2><p>'+esc(g.focus)+'</p></div><div class="route-total"><strong>'+p.percent+'<small>%</small></strong><span>'+p.done+' / '+p.total+' 阶段完成</span><div class="progress"><i style="width:'+p.percent+'%"></i></div></div></header><div class="roadmap-tools">'+button('＋ 添加阶段','newMilestone',g.id,'secondary')+button('编辑路线','goal',g.id,'text-button')+'</div><div class="stage-table"><div class="stage-columns"><span>阶段任务</span><span>状态</span><span>进度</span><span>开始日期</span><span>结束日期</span><span></span></div><div class="stage-list">'+(g.milestones||[]).map((m,i)=>milestoneRow(g,m,i)).join('')+'</div></div>'+(g.milestones?.length?'':blank('添加第一个阶段','写下一项有明确完成标准的任务目标。',button('添加阶段','newMilestone',g.id,'primary')))+'</section>';}).join('')+'</div>'+(state.goals.length?'':blank('从一个主目标开始','按顺序列出要完成的阶段任务。',button('创建路线','newGoal','','primary')));}
function stageStatusClass(status){return status==='已完成'?'done':status==='进行中'?'active':status==='暂停'?'paused':'todo';}
function milestoneCell(m,field,type='text'){return '<input class="milestone-cell" type="'+type+'" data-mfield="'+field+'" data-id="'+esc(m.id)+'" value="'+esc(m[field]||'')+'" aria-label="'+esc(m.name)+(field==='start'?'开始日期':field==='end'?'结束日期':'完成标准')+'">';}
function stageControls(g,m){const p=milestoneProgress(state,g,m);return '<div class="stage-status"><label><span>状态</span><select data-mfield="status" data-id="'+esc(m.id)+'" class="stage-status-select '+stageStatusClass(p.status)+'" aria-label="'+esc(m.name)+'状态">'+options(stageStatuses,p.status)+'</select></label></div><div class="stage-progress"><label><span>进度</span><div class="stage-percent-input"><input type="number" min="0" max="100" step="1" value="'+p.percent+'" data-mfield="progress" data-id="'+esc(m.id)+'" aria-label="'+esc(m.name)+'进度"><span>%</span></div></label><div class="progress" role="progressbar" aria-label="'+esc(m.name)+'完成进度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="'+p.percent+'"><i style="width:'+p.percent+'%"></i></div></div><label class="stage-date"><span>开始日期</span>'+milestoneCell(m,'start','date')+'</label><label class="stage-date"><span>结束日期</span>'+milestoneCell(m,'end','date')+'</label>';}
function milestoneRow(g,m,i){const p=milestoneProgress(state,g,m);return '<article class="stage-row"><div class="stage-name"><span class="milestone-number">'+String(i+1).padStart(2,'0')+'</span><div>'+button(esc(m.name),'milestone',m.id,'task-name')+'<p>'+esc(m.criteria||'点击阶段补充完成标准')+'</p></div></div>'+stageControls(g,m)+'<div class="stage-action">'+button(p.status==='已完成'?'查看记录':p.status==='进行中'?'继续执行':'开始执行',p.status==='已完成'?'milestone':'stageExecute',m.id,p.status==='已完成'?'text-button':'primary')+'</div></article>';}
function milestoneOptions(t){return '<label class="span">所属路线阶段（可选）<select name="milestone"><option value="">暂不关联</option>'+state.goals.map(g=>(g.milestones||[]).map(m=>'<option value="'+esc(m.id)+'" '+(t.milestone===m.id?'selected':'')+'>'+esc(g.name)+' / '+esc(m.name)+'</option>').join('')).join('')+'</select></label>';}
function milestoneForm(goalId,m={}){show('<h2>'+(m.id?'编辑阶段':'添加阶段')+'</h2><form id="milestoneForm" data-id="'+esc(m.id||'')+'" data-goal="'+esc(goalId)+'"><label>阶段任务名称<input name="name" value="'+esc(m.name)+'" required placeholder="例如：完成列表与函数练习"></label><label>完成标准<textarea name="criteria" placeholder="做出什么结果，就算完成这个阶段">'+esc(m.criteria)+'</textarea></label><label>备注<textarea name="notes">'+esc(m.notes)+'</textarea></label><details><summary>起止日期（可选）</summary><div class="form-grid"><label>开始日期<input type="date" name="start" value="'+esc(m.start||'')+'"></label><label>结束日期<input type="date" name="end" value="'+esc(m.end||'')+'"></label></div></details><button class="primary">保存阶段</button></form>');}
function openMilestone(id){const g=state.goals.find(g=>g.milestones?.some(m=>m.id===id));if(!g)return;const m=g.milestones.find(m=>m.id===id),p=milestoneProgress(state,g,m),logs=state.sessions.filter(s=>p.tasks.some(t=>t.id===s.task));show('<div class="stage-detail"><p class="section-label">'+esc(g.name)+'</p><h2>'+esc(m.name)+'</h2><div class="stage-detail-properties">'+stageControls(g,m)+'</div><h3>完成标准</h3><p>'+esc(m.criteria||'尚未填写完成标准')+'</p>'+(m.notes?'<h3>备注</h3><p class="steps">'+esc(m.notes)+'</p>':'')+'<div class="actions">'+button(p.status==='已完成'?'再次执行':'开始执行','stageExecute',id,'primary')+button('编辑阶段','editMilestone',id,'secondary')+'</div>'+(logs.length?'<h3>执行记录</h3>'+logs.slice().reverse().map(s=>'<article class="stage-log"><small>'+esc(new Date(s.at).toLocaleDateString('zh-CN'))+' · '+s.minutes+' 分钟</small><p class="steps">'+esc(s.note)+'</p></article>').join(''):'')+'<small>阶段完成进度不等于知识掌握程度。</small></div>');}
function executeStage(id){ensureStages(state);const g=state.goals.find(g=>g.milestones?.some(m=>m.id===id)),m=g?.milestones.find(m=>m.id===id);if(!m)return;const t=state.tasks.find(t=>t.id===m.taskId);if(!t)return;if(m.status!=='已完成')updateStage(state,g,m,'status','进行中');persist();executeTask(t.id);}

function projects(){return pageHead('项目推进','把要做的任务、已经作出的决定和开发结果放在一起。',button('＋ 新建项目','newProject','','primary'))+`<div class="project-grid">${state.projects.map(p=>{const ts=state.tasks.filter(t=>t.project===p.id),done=ts.filter(t=>t.status==='完成').length;return `<section class="panel project-card"><span class="section-label">项目</span><h2>${esc(p.name)}</h2><p>${esc(p.purpose)}</p><div class="progress"><i style="width:${ts.length?done/ts.length*100:0}%"></i></div><small>${done} / ${ts.length} 项任务完成</small><div class="section-head"><h3>关联任务</h3>${button('＋ 新任务','projectTask',p.id,'text-button')}</div>${ts.map(taskRow).join('')||'<p class="quiet-empty">添加第一项任务，把项目推进起来。</p>'}<details><summary>决定与最近结果</summary><p>${esc(p.decisions||'尚未记录决定')}</p><p>${esc(p.result||'尚未记录结果')}</p></details><div class="actions">${button('编辑项目','project',p.id,'secondary')}${button('生成开发说明','brief',p.id,'text-button')}</div></section>`}).join('')||blank('把正在做的东西建成项目','项目可以关联任务，并保留开发上下文。',button('新建项目','newProject','','primary'))}</div>`;}

function review(){const logs=state.sessions.filter(s=>Date.now()-Date.parse(s.at)<7*86400000),inbox=state.inbox.filter(i=>!i.archived),pending=state.tasks.filter(t=>['进行中','部分完成'].includes(t.status));return pageHead('整理与复盘','先处理没收尾的事，再记录今天的进展。')+`<div class="review-tabs">${[['night','每日收尾'],['weekly','每周回顾'],['history','历史记录']].map(([key,label])=>`<button class="view-tab ${reviewTab===key?'selected':''}" data-action="reviewTab" data-id="${key}" aria-pressed="${reviewTab===key}">${label}</button>`).join('')}</div>${reviewTab==='night'?`<div class="review-layout"><div><section class="review-step"><div class="step-heading"><span>01</span><div><h2>整理收件箱</h2><p>要做的转为任务，其余归档。</p></div><b>${inbox.length}</b></div>${inbox.map(i=>`<div class="inbox-row"><p>${esc(i.text)}<small>${new Date(i.at).toLocaleString('zh-CN')}</small></p><div>${button('转为任务','inboxTask',i.id,'secondary')}${button('归档','archive',i.id,'text-button')}</div></div>`).join('')||'<p class="quiet-empty">收件箱已清空。</p>'}</section><section class="review-step"><div class="step-heading"><span>02</span><div><h2>处理未完成的任务</h2><p>继续做，或调整状态和截止日期。</p></div><b>${pending.length}</b></div>${pending.map(taskRow).join('')||'<p class="quiet-empty">没有进行中或部分完成的任务。</p>'}</section><section class="review-step"><div class="step-heading"><span>03</span><div><h2>留下进展，确定明天</h2><p>写下实际发生的事，不必写成长篇总结。</p></div></div><form id="nightForm"><label>今天做到了什么？卡在哪里？<textarea name="note" required placeholder="完成了什么；哪里需要再试一次。">${esc(state.notes.night||'')}</textarea></label><label>明天先做什么？<textarea name="next" required placeholder="写一个明确的行动。">${esc(state.notes.nightNext||'')}</textarea></label><small>这里保存的是明日草案；需要安排到期时间时，在任务计划中调整。</small><div class="actions"><button class="primary">保存今日收尾</button></div></form></section></div><section class="panel review-aside"><span class="section-label">近 7 天</span><strong class="time-number">${logs.reduce((a,s)=>a+s.minutes,0)}<span> 分钟</span></strong><p>${logs.filter(s=>s.status==='完成').length} 次完成记录</p><p>${logs.filter(s=>s.status==='部分完成').length} 次部分完成记录</p><a href="#tasks">查看任务计划</a></section></div>`:reviewTab==='weekly'?`<section class="panel"><div class="section-head"><div><h2>本周成果</h2><p>根据真实记录，决定下周继续推进什么。</p></div>${button('开始本周回顾','weekly','','primary')}</div>${state.outcomes.map(o=>`<div class="task"><div><strong>${esc(o.name)}</strong><small>${esc(o.decision||'继续')} · ${esc(o.reason||'')}</small></div>${button(o.done?'已完成 · 撤销':'标记完成','outcome',o.id,o.done?'text-button':'secondary')}</div>`).join('')||blank('还没有本周成果','开始回顾后，选择 3–5 个下周要完成的成果。')}</section>`:`<section class="panel">${state.reviews.slice().reverse().map(r=>`<article class="review-history"><span class="section-label">${r.date} · ${r.type==='night'?'每日收尾':'每周回顾'}</span><h3>进展与发现</h3><p class="steps">${esc(r.note)}</p><h3>下一步</h3><p class="steps">${esc(r.next||'未填写')}</p></article>`).join('')||blank('还没有复盘记录','完成一次每日收尾后，就会在这里留下记录。')}</section>`}`;}

function render(){if(!ready)return;const key=labels[view()]?view():'today';$('#date').textContent=dateLabel(day());$('#toolbarTitle').textContent=labels[key];$('#workspaceStatus').textContent=state.tasks.length+' 项任务 · '+state.tasks.filter(t=>t.status==='完成').length+' 项完成';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+key));$('#view').innerHTML=({today,tasks,calendar,goals,projects,review})[key]();markSelection();}
function taskForm(t={}){show(`<h2>${t.id?'编辑任务':'新建任务'}</h2><form id="taskForm" data-id="${t.id||''}"><div class="form-grid"><label class="span">任务名称<input name="name" required maxlength="180" value="${esc(t.name)}"></label><label class="span">做到什么算完成？<textarea name="criteria" placeholder="例如：运行四组测试，保留代码与输出">${esc(t.criteria)}</textarea></label><label class="span">第一步做什么？<input name="minimum" value="${esc(t.minimum)}" placeholder="例如：新建 find_max.py，写下函数定义"></label>${milestoneOptions(t)}<label>领域<select name="domain">${options(domains,t.domain)}</select></label><label>预计分钟<input name="minutes" type="number" min="5" max="1440" value="${t.minutes||30}" required></label><details class="span form-advanced"><summary>日期、优先级与关联（可选）</summary><div class="form-grid"><label>安排到哪一天<input name="plannedDate" type="date" value="${esc(t.plannedDate||'')}"></label><label>几点开始<input name="plannedTime" type="time" value="${esc(t.plannedTime||'')}"></label></div><label>类型<select name="kind">${options(['核心','轻量'],t.kind)}</select></label><label>截止日期<input name="due" type="date" value="${t.due||''}"></label><label>优先级<select name="priority"><option value="1" ${t.priority===1?'selected':''}>高</option><option value="2" ${!t.priority||t.priority===2?'selected':''}>中</option><option value="3" ${t.priority===3?'selected':''}>低</option></select></label><label>认知负荷<select name="load">${options(['高','中','低'],t.load||'中')}</select></label><label>状态<select name="status">${options(['待办','进行中','部分完成','等待','以后','完成'],t.status||'待办')}</select></label><label>关联项目<select name="project"><option value="">无</option>${state.projects.map(p=>`<option value="${p.id}" ${p.id===t.project?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><details class="span form-advanced"><summary>关联目标与执行细节（可选）</summary><fieldset><legend>关联目标（可不选、可多选）</legend>${state.goals.map(g=>`<label class="check"><input type="checkbox" name="goals" value="${g.id}" ${t.goals?.includes(g.id)?'checked':''}>${esc(g.name)}</label>`).join('')||'可先在目标页创建目标。'}</fieldset><label class="span">执行步骤（每行一步）<textarea name="steps">${esc(t.steps?.join('\n'))}</textarea></label><label class="span">资料与入口（可填写网址）<textarea name="materials">${esc(t.materials)}</textarea></label><label class="span">短讲解与示例<textarea name="lesson">${esc(t.lesson)}</textarea></label></details></details></div><div class="actions"><button class="primary" type="submit" name="after" value="start">保存并开始</button><button class="secondary" type="submit">只保存，稍后做</button></div></form>`);}
function resources(text){return esc(text).replace(/https?:\/\/[^\s<&]+/g,u=>`<a href="${u}" target="_blank" rel="noopener noreferrer">${u}</a>`);}

function focusControls(id){return '<div class="focus-controls"><strong class="timer" id="timer">00:00</strong><span id="focusState">未计时</span>'+button('开始计时','timer',id,'secondary')+button('暂停','pauseFocus',id,'text-button')+button('结束并记录','focusResult',id,'text-button')+'</div>';}
function updateFocusClock(){if(!activeSession)return;if($('#focusState'))$('#focusState').textContent=activeSession.paused?'已暂停':'专注中';const seconds=Math.floor(focusElapsed(activeSession)/1000);if($('#timer'))$('#timer').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');if($('#sessionMinutes'))$('#sessionMinutes').value=Math.max(1,Math.round(seconds/60));}
function pauseFocus(){if(activeSession&&!activeSession.paused){activeSession.elapsed=focusElapsed(activeSession);activeSession.paused=true;clearInterval(tick);updateFocusClock();}}
function setPhase(id){document.querySelectorAll('[data-pane]').forEach(el=>el.hidden=el.dataset.pane!==id);document.querySelectorAll('[data-action=phase]').forEach(el=>{el.classList.toggle('selected',el.dataset.id===id);el.setAttribute('aria-pressed',String(el.dataset.id===id));});$('#dialog').scrollTop=0;}
function executeTask(id){const t=state.tasks.find(t=>t.id===id);if(!t)return;if(t.domain==='学习')return openLearning(t);if(!['完成','进行中'].includes(t.status))change(()=>{t.status='进行中';syncStageResult(state,t);});
show('<div class="learning">'+routeContext(t)+'<p class="eyebrow">专注执行 · '+esc(t.domain)+'</p><h2>'+esc(t.name)+'</h2>'+focusControls(id)+'<div class="execution-tabs">'+button('1 · 执行','phase','try','view-tab selected')+button('2 · 记录结果','phase','result','view-tab')+'</div><section data-pane="try" class="practice-block">'+(t.resume?'<div class="alert">上次做到：'+esc(t.resume)+'</div>':'')+'<h3>先做这一步</h3><p>'+esc(t.minimum||t.steps[0]||'先做十分钟，再留下实际进展。')+'</p><h3>完成标准</h3><p>'+esc(t.criteria||'留下一个可以检查的成果。')+'</p>'+(t.steps.length?'<details><summary>执行步骤</summary>'+t.steps.map((x,i)=>'<label class="check"><input type="checkbox" data-step="'+i+'" data-task="'+id+'" '+(t.checked.includes(i)?'checked':'')+'>'+esc(x)+'</label>').join('')+'</details>':'')+(t.materials?'<details><summary>资料（可选）</summary>'+resources(t.materials)+'</details>':'')+'<div class="actions">'+button('完成或卡住了，记录结果','focusResult',id,'primary')+'</div></section><section data-pane="result" hidden class="practice-block"><form id="sessionForm" data-id="'+id+'"><label>做出了什么？下次从哪里继续？<textarea name="note" required>'+esc(state.notes[id]||'')+'</textarea></label><div class="form-grid"><label>实际分钟<input name="minutes" id="sessionMinutes" type="number" min="1" max="1440" value="10" required></label><label>本次结果<select name="status">'+options(['部分完成','完成','等待'],'部分完成')+'</select></label></div><label>停止原因<select name="reason">'+options(['正常完成','时间不够','卡住了','临时有事'],'正常完成')+'</select></label><button class="primary">保存本次结果</button></form></section><details class="secondary-panel"><summary>执行中随手记</summary><form id="inlineCaptureForm"><input name="text" required aria-label="想法或临时事务" placeholder="先记下来，继续专注"><button>放入收件箱</button></form></details></div>','execution-dialog');}

function goalForm(g={}){show(`<h2>${g.id?'编辑路线':'新建路线'}</h2><form id="goalForm" data-id="${esc(g.id||'')}"><label>主目标<input name="name" value="${esc(g.name)}" required placeholder="例如：能独立开发一个 Python 小工具"></label><label>当前重心<input name="focus" value="${esc(g.focus)}" required></label>${!g.id?'<label>拆成哪些阶段任务？（每行一项）<textarea name="route" required placeholder="变量、条件与循环；列表与函数；完成一个小工具（每行一项）"></textarea></label>':'<p class="muted">阶段任务的名称、日期和完成标准，在路线中分别编辑。</p>'}<label class="check"><input name="primary" type="checkbox" ${g.primary?'checked':''}>设为主路线</label><button class="primary">保存主目标</button></form>`);}
function eventForm(e={}){show(`<h2>${e.id?'编辑':'添加'}固定日程</h2><form id="eventForm" data-id="${e.id||''}"><label>事项<input name="name" value="${esc(e.name)}" required></label><label>日期<input name="date" type="date" value="${e.date||currentDate}" required></label><div class="form-grid"><label>开始<input name="start" type="time" value="${e.start||'09:00'}" required></label><label>结束<input name="end" type="time" value="${e.end||'10:00'}" required></label></div><button class="primary">保存日程</button>${e.id?button('移除日程','deleteEvent',e.id):''}</form>`);}
function projectForm(p={}){show(`<h2>${p.id?'项目详情':'新建项目'}</h2><form id="projectForm" data-id="${p.id||''}"><label>项目名称<input name="name" value="${esc(p.name)}" required></label><label>为什么做<textarea name="purpose" required>${esc(p.purpose)}</textarea></label><label>GitHub 仓库链接<input name="url" type="url" value="${esc(p.url)}"></label><label>已做的决定、当前卡点<textarea name="decisions">${esc(p.decisions)}</textarea></label><label>最近开发结果与验收证据<textarea name="result">${esc(p.result)}</textarea></label><button class="primary">保存项目</button></form>${p.url&&/^https?:\/\//.test(p.url)?`<p><a href="${esc(p.url)}" target="_blank" rel="noopener">打开仓库</a></p>`:''}${p.id?state.tasks.filter(t=>t.project===p.id).map(taskRow).join(''):''}`);}
function night(){const pending=state.tasks.filter(t=>['进行中','部分完成'].includes(t.status));const tomorrow=new Date(Date.now()+86400000),plan=schedule({...state,settings:{...state.settings,minutes:120}},new Date(day(tomorrow)+'T09:00:00'));show(`<h2>晚间整理</h2><p>收件箱 ${state.inbox.filter(i=>!i.archived).length} 项待整理；${pending.length} 项任务有未完成进展。可先关闭窗口，在复盘页处理。</p>${pending.map(taskRow).join('')}<form id="nightForm"><label>今天的进展与卡点<textarea name="note" required>${esc(state.notes.night||'')}</textarea></label><label>明日草案（可修改，保存后不会自动改动任务）<textarea name="next" required>${esc(plan.core.map(t=>t.name).join('\n')||'先明确一个能立即开始的任务。')}</textarea></label><button class="primary">确认并保存晚间整理</button></form>`);}
function weekly(){const logs=state.sessions.filter(s=>Date.now()-Date.parse(s.at)<7*86400000),planned=logs.reduce((a,s)=>a+s.estimate,0),actual=logs.reduce((a,s)=>a+s.minutes,0);const candidates=state.tasks.filter(t=>t.status!=='完成').sort((a,b)=>a.priority-b.priority).slice(0,8);show(`<h2>每周复盘</h2><p>近七天预计 ${planned} 分钟，实际 ${actual} 分钟。${planned&&actual>planned?'实际耗时超过估计；建议缩小下周任务量，或提高估时。':'先根据实际记录判断下周容量。'}</p><form id="weeklyForm"><h3>候选成果 · 选择或修改 3–5 项</h3>${candidates.map(t=>`<label class="check"><input type="checkbox" name="candidate" value="${t.id}">${esc(t.name)} · ${t.due?'截止 '+esc(t.due):'推进 '+esc(t.domain)}</label>`).join('')}<label>补充或重写成果（每行一项，与勾选项合并）<textarea name="extra"></textarea></label><h3>上周未完成成果</h3>${state.outcomes.filter(o=>!o.done).map(o=>`<label>${esc(o.name)}<select name="decision-${o.id}">${options(['继续','缩小','拆分','延后','放弃'],o.decision||'继续')}</select><input name="reason-${o.id}" placeholder="实际进度与未完成原因" required></label>`).join('')||'<p class="muted">没有待处理成果。</p>'}<label>规律、原因与调整决定<textarea name="note" required>${esc(state.notes.weekly||'')}</textarea></label><button class="primary">确认下周成果并保存</button></form>`);}
