$('#add').onclick=()=>{if(activeSession)return toast('请先记录当前执行结果。');if(ready)taskForm();};$('#capture').onclick=()=>{if(!ready)return;if(activeSession)return toast('请使用执行空间内的随手记。');show('<h2>五秒随手记</h2><p class="muted">先放进收件箱，晚上统一整理。</p><form id="captureForm"><label>想法或待办<textarea name="text" required autofocus></textarea></label><button class="primary">放入收件箱</button></form>');};$('#export').onclick=()=>state&&exportData();$('#retry').onclick=()=>state&&persist();$('#reload').onclick=()=>{if(dirty){show(`<h2>当前还有未保存的修改</h2><p>请先导出备份或重试保存；加载云端会替换当前草稿。</p><button id="exportDraft">导出当前草稿</button><button data-action="discardDraft">放弃当前草稿并加载云端</button>`);$('#exportDraft').onclick=exportData;return;}load();};$('#dialog').addEventListener('cancel',e=>{if(activeSession){e.preventDefault();toast('请先记录执行结果或取消计时。');}});window.addEventListener('hashchange',()=>{closeInspector();render();$('#contentScroll').scrollTop=0;});window.addEventListener('beforeunload',e=>{if(dirty||activeSession){e.preventDefault();e.returnValue='';}});window.addEventListener('focus',()=>{if(ready&&!dirty&&!saving&&!$('#dialog').open)load();});load();

