function resultRoute(t){const g=taskGoal(t),m=g?.milestones?.find(m=>m.id===t.milestone);if(!g)return '';const p=routeProgress(state,g),mp=m?milestoneProgress(state,g,m):null;return '<section class="result-route"><strong>'+esc(g.name)+'</strong><p>'+(m?esc(m.name)+' · '+mp.status+' · '+mp.percent+'%':'路线进度 · '+p.percent+'%')+'</p><div class="progress" role="progressbar" aria-label="路线完成进度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="'+p.percent+'"><i style="width:'+p.percent+'%"></i></div><a href="#goals" class="result-route-link">查看目标路线</a></section>';}
