function helpMarkup(t){const items=t.exercise?.help||(t.lesson?[{title:'相关知识讲解',text:t.lesson}]:[]),seen=t.helpSeen||[],count=seen.length;return `<div class="help-content">${items.slice(0,count).map(h=>`<details open><summary>${esc(h.title)}</summary><pre>${esc(h.text)}</pre></details>`).join('')}${count<items.length?`<button type="button" data-action="hint" data-id="${t.id}" data-level="${count}">${count?'查看下一层：':'我卡住了：'}${esc(items[count].title)}</button>`:'<p class="muted">看过参考后，可以先理解，再合上它重新尝试。</p>'}</div>`;}
function openLearning(t){
 const x=t.exercise;if(!['完成','进行中'].includes(t.status))change(()=>{t.status='进行中';syncStageResult(state,t);});
 show(`<div class="learning">${routeContext(t)}<p class="eyebrow">${x?'PYTHON PRACTICE':'学习练习'} · ${t.minutes} 分钟</p><h2>${esc(t.name)}</h2><p>${esc(x?.prompt||t.criteria)}</p>${focusControls(t.id)}<div class="execution-tabs">${[['try','1 · 尝试'],['help','卡住时 · 获取帮助'],['result','2 · 验收与记录']].map(([key,label])=>`<button data-action="phase" data-id="${key}" class="view-tab ${key==='try'?'selected':''}" aria-pressed="${key==='try'}">${label}</button>`).join('')}</div>
 ${x?`<section class="practice-block" data-pane="try"><h3>在电脑上写，在这里记录结果</h3><p>在电脑编辑器中新建 <code>${esc(x.file)}</code>，写下函数并补全。手机上可以先想思路，回到电脑再运行。</p><pre>${esc(x.starter)}</pre><p class="muted">先独立尝试十分钟；想不出第一步就点下方「我卡住了」。</p><h3>用这些测试检查结果</h3><p class="muted">把测试放在函数下面。</p><pre>${esc(x.tests)}</pre><p>在文件所在目录打开终端，Mac 运行 <code>python3 ${esc(x.file)}</code>，Windows 运行 <code>py ${esc(x.file)}</code>。</p><p class="muted">此页面不运行代码。若提示找不到 Python 命令，先完成电脑的 Python 安装。</p></section>`:`<section class="practice-block" data-pane="try"><h3>先尝试</h3><p class="steps">${esc(t.steps.join('\n'))}</p><p>${esc(t.minimum||'在自己的编辑器或练习本中完成，再回来记录。')}</p></section>`}
 <div class="execution-next" data-pane="try">${button('我已运行，记录结果','phase','result','primary')}${button('我卡住了','phase','help','secondary')}${button('先停在这里，留下进展','phase','result','text-button')}</div>${t.resume?`<div class="alert">上次做到这里：${esc(t.resume)}</div>`:''}
 <section class="practice-block" data-pane="help" hidden><h3>02 / 卡住时再看</h3>${helpMarkup(t)}<div class="actions">${button('回去继续尝试','phase','try','primary')}${button('暂时没解决，记录卡点','phase','result','text-button')}</div>${t.materials?`<details class="resources"><summary>拓展资料（可选）</summary><div class="steps">${resources(t.materials)}</div></details>`:''}</section>
 <section class="practice-block" data-pane="result" hidden><h3>做到哪一步，就记录哪一步</h3><p>${esc(t.criteria)}</p><p class="muted">根据你在本地的运行结果自验，页面不会自动判题。查看帮助会记入本次记录。</p>
 <form id="sessionForm" data-id="${t.id}"><label>代码结果或卡住的位置<textarea name="note" required placeholder="例如：三个测试通过；空列表还会报错。也可以粘贴代码。">${esc(state.notes[t.id]||'')}</textarea></label><div class="form-grid"><label>实际投入（分钟）<input id="sessionMinutes" name="minutes" type="number" min="1" max="1440" value="10" required></label><label>本次结果<select name="status"><option value="部分完成">还需继续</option><option value="完成">本次练习完成</option></select></label></div><label class="check"><input type="checkbox" name="passed">我已运行测试并按完成标准自验通过</label><label class="check"><input type="checkbox" name="independent">我能独立写出并解释实现</label><button class="primary">保存本次结果</button></form></section>
 <details class="secondary-panel"><summary>历史记录与任务设置</summary>${state.sessions.filter(s=>s.task===t.id).slice().reverse().map(s=>`<p><small>${new Date(s.at).toLocaleString('zh-CN')} · ${s.minutes} 分钟 · ${esc(s.status)}</small><br>${esc(s.note)}</p>`).join('')||'<p>还没有执行记录。</p>'}${t.previousLearningContent?'<p class="muted">已将原始 Java 示例更新为 Python；旧内容与历史记录已保留。</p>':''}${button('编辑任务','editTask',t.id)}</details></div>`,'execution-dialog');
}
function learningResult(t){const plan=schedule(state),next=[...plan.core,...plan.quick].find(n=>n.id!==t.id),done=t.status==='完成';show(`<div class="result"><p class="eyebrow">本次结果已记录 · ${esc(t.name)}</p><h2>${done?'这一项做完了。':'进展已留下，下次不用从头开始。'}</h2><div class="result-receipt"><p>${esc(state.sessions.filter(x=>x.task===t.id).at(-1)?.note||t.resume)}</p></div>${resultRoute(t)}${done&&t.domain==='学习'&&t.mastery!=='已验收'?`<p>待复测：${t.reviewAt?new Date(t.reviewAt).toLocaleDateString('zh-CN'):'两天后'}。到时从首页继续；本次记录不等于已掌握。</p>`:''}<h3>${done?'接下来':'下次从这里继续'}</h3>${!done?`<p>${esc(t.resume)}</p>${button('继续这项任务','execute',t.id,'primary')}`:next?`<p>${esc(next.name)} · 预计 ${next.duration||next.estimate} 分钟</p>${button('开始下一项','execute',next.id,'primary')}`:'<p>当前预算内没有其他安排，可以收尾休息。</p>'}<div class="actions">${button('今天先到这里，去收尾','finishDay','','secondary')}${button('回到今日','home','','text-button')}</div></div>`);}

document.addEventListener('focusout',e=>{if(ready&&e.target.name==='note')persist();});

function openTask(id){const t=state.tasks.find(t=>t.id===id);if(!t)return;selectedTaskId=id;show(`<div class="detail-top"><span class="section-label">任务详情 · ${esc(t.domain)}</span><h2>${esc(t.name)}</h2>${statusBadge(t)}</div><div class="detail-properties"><label>状态<select data-field="status" data-id="${t.id}">${options(['待办','进行中','部分完成','等待','以后','完成'],t.status)}</select></label><label>截止日期<input type="date" data-field="due" data-id="${t.id}" value="${t.due||''}"></label><p><small>预计投入</small><strong>${t.minutes} 分钟</strong></p><p><small>关联目标 / 项目</small><strong>${relations(t)}</strong></p></div><section class="detail-section"><h3>完成后应得到什么</h3><p>${esc(t.criteria||'尚未填写完成标准')}</p></section><section class="detail-section"><h3>从哪里开始</h3><p>${esc(t.resume||t.minimum||t.steps[0]||'进入执行空间，记录第一个步骤。')}</p></section><div class="detail-actions">${button(t.status==='完成'?'进入练习 / 复测':'开始执行','execute',t.id,'primary')}${button('编辑任务','editTask',t.id,'secondary')}</div><details class="secondary-panel"><summary>历史执行 · ${state.sessions.filter(s=>s.task===id).length} 次</summary>${state.sessions.filter(s=>s.task===id).slice().reverse().map(s=>`<p><small>${new Date(s.at).toLocaleString('zh-CN')} · ${s.minutes} 分钟 · ${esc(s.status)}</small><br>${esc(s.note)}</p>`).join('')||'<p>暂无记录。</p>'}</details>`,'drawer');}

function markSelection(){document.querySelectorAll('[data-action="task"]').forEach(el=>{const selected=el.dataset.id===selectedTaskId;el.classList.toggle('selected-task',selected);el.closest('tr, .board-card, .task')?.classList.toggle('selected-row',selected);});}
function closeInspector(){selectedTaskId=null;$('#inspector').hidden=true;$('#appWindow').classList.remove('with-inspector');markSelection();}
$('#toggleSidebar').onclick=()=>$('#appWindow').classList.toggle('sidebar-collapsed');
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){if($('#dialog').open)return;e.preventDefault();if(view()!=='tasks'){location.hash='tasks';setTimeout(()=>$('#search')?.focus(),0);}else $('#search')?.focus();}if(e.key==='Escape'&&!$('#dialog').open)closeInspector();});
